  str_files_story_title_5305 = "幸福の金・3",
  str_files_story_des_101 = "「基本情報収集表」を記入していないのはあとナシリス1人だけだ。なぜこういうことに抵抗があるのだろうか…？",
  str_files_story_des_103 = "なんと2人の「ナシリス」に遭遇した。1人はまさか、いつも彼女が言っている「お姉さま」！？まったく見分けがつかない…",
  str_files_story_des_105 = "ストーリー5",
  str_files_story_des_107 = "ストーリー7",
  str_files_story_des_110 = "ストーリー10",
  str_files_story_des_201 = "最近刺すような「視線」が背後からいつもあなたを追いかけている。「そいつ」を誘い出すため、下手な芝居をやってのけることにする…",
  str_files_story_des_203 = "長官は意外にも人当りがいいようだ。でもあの強大なオーラは、人を居たたまれなくさせる――聞きたいことがあるけど、聞いてもいいのか…",
  str_files_story_des_205 = "ストーリー5",
  str_files_story_des_207 = "ストーリー7",
  str_files_story_des_209 = "ストーリー9",
  str_files_story_des_210 = "ストーリー10",
  str_files_story_des_402 = "ストーリー2",
  str_files_story_des_404 = "ストーリー4",
  str_files_story_des_406 = "ストーリー6",
  str_files_story_des_408 = "ストーリー8",
  str_files_story_des_501 = "ストーリー1",
  str_files_story_des_503 = "ストーリー3",
  str_files_story_des_505 = "ストーリー5",
  str_files_story_des_507 = "ストーリー7",
  str_files_story_des_509 = "ストーリー9",
  str_files_story_des_510 = "ストーリー10",
  str_files_story_des_602 = "城主様の娘さんと付き合うのは、やはり一筋縄ではいかない。リーダーとしての風格を出そうとしたが、その結果は…",
  str_files_story_des_604 = "カレンはどうやら自分の立場に「矛盾」を感じているようだ。「読解」が苦手なあなたはどうしたら彼女の心を開くことができるのだろう…",
  str_files_story_des_606 = "ストーリー6",
  str_files_story_des_608 = "ストーリー8",
  str_files_story_des_609 = "ストーリー9",
  str_files_story_des_610 = "ストーリー10",
  str_files_story_des_802 = "ストーリー2",
  str_files_story_des_804 = "ストーリー4",
  str_files_story_des_806 = "ストーリー6",
  str_files_story_des_901 = "ストーリー1",
  str_files_story_des_903 = "ストーリー3",
  str_files_story_des_905 = "ストーリー5",
  str_files_story_des_907 = "ストーリー7",
  str_files_story_des_910 = "ストーリー10",
  str_files_story_des_1002 = "ストーリー2",
  str_files_story_des_1004 = "ストーリー4",
  str_files_story_des_1006 = "ストーリー6",
  str_files_story_des_1008 = "ストーリー8",
  str_files_story_des_1009 = "ストーリー9",
  str_files_story_des_1102 = "恒例検閲日でもないのに異常なプレッシャーを感じる――啓光軍団長の1人であるキシローナが巨像の運営をチェックする！？順調にいきますように…",
  str_files_story_des_1104 = "キシローナが巨像とあなたに大きな関心を持っているのには、どうやら「彼女なりの理由」があるようだ。もしかしたらあなたに期待できる何かを見出したのかも…",
  str_files_story_des_1106 = "ストーリー5",
  str_files_story_des_1108 = "ストーリー7",
  str_files_story_des_1110 = "ストーリー10",
  str_files_story_des_1201 = "「ささいな事」が原因で、巨像ないに大音量で言い争う声が響いた！あなたの意志に関わらず、「仲裁人」になる必要があるらしい…",
  str_files_story_des_1203 = "ナミシスさんはどうやら「公平と正義」に非常に強い執着があるようだ。少し時間をとって話したほうがいいかもしれない。彼女の知られざる一面を知るためにも…",
  str_files_story_des_1205 = "ストーリー5",
  str_files_story_des_1207 = "ストーリー7",
  str_files_story_des_1210 = "ストーリー10",
  str_files_story_des_1302 = "ストーリー2",
  str_files_story_des_1304 = "ストーリー4",
  str_files_story_des_1306 = "ストーリー6",
  str_files_story_des_1308 = "ストーリー8",
  str_files_story_des_1309 = "ストーリー9",
  str_files_story_des_1310 = "ストーリー10",
  str_files_story_des_1402 = "城主様みずから巨像を視察！？慌てふためいたあなたはのっけから遅刻。続きはくれぐれもミスしないように――できる限りね！",
  str_files_story_des_1404 = "「穏やかで親しみやすい」城主様がまたもや物凄い剣幕であなたの前に現れた――これは一体どういうこと？巨像の責任者として、あなたは再び「期待」と「失望」の入り混じる視線にさらされる…",
  str_files_story_des_1406 = "ストーリー6",
  str_files_story_des_1408 = "ストーリー8",
  str_files_story_des_1409 = "ストーリー9",
  str_files_story_des_1410 = "ストーリー10",
  str_files_story_des_1701 = "ストーリー1",
  str_files_story_des_1703 = "ストーリー3",
  str_files_story_des_1705 = "ストーリー5",
  str_files_story_des_1707 = "ストーリー7",
  str_files_story_des_1802 = "音楽ライブの招待状？せっかくの休みを投げうってでも、この奇妙なイベントに参加すべきか迷っていると、凄まじい勢いでノックする音が聞こえてきた…",
  str_files_story_des_1804 = "今日は約束の日、レジーナのライブって、どんなものだろう？あなたはなんとなく一抹の不安を感じていた――",
  str_files_story_des_1806 = "ストーリー6",
  str_files_story_des_1808 = "ストーリー8",
  str_files_story_des_1809 = "ストーリー9",
  str_files_story_des_1810 = "ストーリー10",
  str_files_story_des_1901 = "ストーリー1",
