  str_files_story_des_1910 = "ストーリー10",
  str_files_story_des_2101 = "ストーリー1",
  str_files_story_des_2103 = "ストーリー3",
  str_files_story_des_2105 = "ストーリー5",
  str_files_story_des_2107 = "ストーリー7",
  str_files_story_des_2201 = "ストーリー1",
  str_files_story_des_2203 = "ストーリー3",
  str_files_story_des_2205 = "ストーリー5",
  str_files_story_des_2301 = "ストーリー3",
  str_files_story_des_2303 = "ストーリー5",
  str_files_story_des_2305 = "ストーリー7",
  str_files_story_des_2307 = "ストーリー9",
  str_files_story_des_2310 = "ストーリー10",
  str_files_story_des_2501 = "またもや変わり映えのしない一日、またもやカロン宛ての「苦情の手紙」が何通か届く…どうやら彼と話してみる必要がありそうだ…",
  str_files_story_des_2503 = "カロンとは、まともに話をすることが出来ないようだ…機会があれば、また情報を集めてみよう。もしかしたらあの「熱狂」ぶりの根源が何なのか、わかるかもしれない…",
  str_files_story_des_2505 = "ストーリー5",
  str_files_story_des_2507 = "ストーリー7",
  str_files_story_des_2509 = "ストーリー9",
  str_files_story_des_2510 = "ストーリー10",
  str_files_story_des_2602 = "ストーリー2",
  str_files_story_des_2604 = "ストーリー4",
  str_files_story_des_2606 = "ストーリー6",
  str_files_story_des_2608 = "ストーリー8",
  str_files_story_des_2609 = "ストーリー9",
  str_files_story_des_2610 = "ストーリー10",
  str_files_story_des_2801 = "なにか良くないことが起こりそうな気がしてならないって…それはいったいなに？あ、遠くに見えるあの人はラファエル？なぜ狂ったように…手招きしているの？",
  str_files_story_des_2803 = "より良い治療法に改善していこうとするラファエルの探究心には本当に…頭が痛む。今日もまた彼女「謀られ」ないことを願うばかりだ。でないとあなたまで苦情の手紙書く羽目になりそうだ…",
  str_files_story_des_2805 = "ストーリー5",
  str_files_story_des_2807 = "ストーリー7",
  str_files_story_des_2809 = "ストーリー9",
  str_files_story_des_2810 = "ストーリー10",
  str_files_story_des_2902 = "ストーリー2",
  str_files_story_des_2904 = "ストーリー4",
  str_files_story_des_2906 = "ストーリー6",
  str_files_story_des_2908 = "ストーリー8",
  str_files_story_des_2909 = "ストーリー9",
  str_files_story_des_2910 = "ストーリー10",
  str_files_story_des_3202 = "ストーリー2",
  str_files_story_des_3204 = "ストーリー4",
  str_files_story_des_3206 = "ストーリー6",
  str_files_story_des_3301 = "1つ質問です：いつも一緒にいるこの「古い友人」のことをあなたはどれくらい知っていますか？彼女の本当の考えをきちんとわかっていますか？もしかしたら、答えはまだまだ深いところにあるのかもしれない…",
  str_files_story_des_3303 = "バイスと「聞き取り調査」をする約束をしたが、なんだか業績評価のような気がしてならない。不安な気持ちのまま約束に出向くあなたは、どういう試験であろうと、バイスが少しでも手加減してくれることを願うばかり…",
  str_files_story_des_3305 = "ストーリー6",
  str_files_story_des_3307 = "ストーリー8",
  str_files_story_des_3310 = "ストーリー10",
  str_files_story_des_3501 = "最近カラスの配達定刻率がひどく下がってるの。一体なにが原因なのかしら？ちょっと話してみましょう…",
  str_files_story_des_3503 = "カラスって方向音痴だったのね…それでこの仕事をするなんて大したものだわ。でも地図を書き写して記憶力って上がるのかしら…",
  str_files_story_des_3505 = "ストーリー5",
  str_files_story_des_3602 = "ストーリー1",
  str_files_story_des_3604 = "ストーリー3",
  str_files_story_des_3606 = "ストーリー5",
  str_files_story_des_3608 = "ストーリー7",
  str_files_story_des_3610 = "ストーリー10",
  str_files_story_des_3802 = "ガルーさんは最近巨像のメンテナンスにとっても熱心、物凄い興味と情熱を抱いているみたい。今日あなたたちは初めて正式に会うけど、彼女、どんな性格なのかしら？",
  str_files_story_des_3804 = "ガルーさんはとてもゲームがお好きなようだわ…それが普段の仕事に影響しないといいのだけれど。でないと困るわ…",
  str_files_story_des_3806 = "ストーリー6",
  str_files_story_des_3808 = "ストーリー8",
  str_files_story_des_3809 = "ストーリー9",
  str_files_story_des_3810 = "ストーリー10",
  str_files_story_des_4001 = "ストーリー1",
  str_files_story_des_4003 = "ストーリー3",
  str_files_story_des_4005 = "ストーリー5",
  str_files_story_des_4007 = "ストーリー7",
  str_files_story_des_4101 = "大規模イベントがあるたび、Ms.ブランはひときわ多忙になる。様子を見に行ったほうがいいのだろうか？手伝いができればいいが、逆に「邪魔」になりやしないか心配だ…",
  str_files_story_des_4103 = "どうやら本当に「かえって邪魔」だったみたい。Ms.ブラン、さらに多忙になってしまったわ…ちょっとでも埋め合わせできる機会はないかしら？",
  str_files_story_des_4105 = "ストーリー5",
  str_files_story_des_4107 = "ストーリー7",
  str_files_story_des_4402 = "ストーリー2",
  str_files_story_des_4404 = "ストーリー4",
  str_files_story_des_4406 = "ストーリー6",
  str_files_story_des_4408 = "ストーリー8",
  str_files_story_des_4601 = "ストーリー1",
  str_files_story_des_4603 = "ストーリー3",
  str_files_story_des_4605 = "ストーリー5",
  str_files_story_des_4701 = "最近ゾーヤの行動がちょっと怪しいわ――いつもどこかをさまよい、現れたかと思うとまた消えてしまう。なんだか…なにかを観察しているのかしら？",
  str_files_story_des_4703 = "ゾーヤがヒイロ長官に「特別な」依存心を抱いていたとは…彼女のことをもっと知りたいと思うが、ゾーヤは話してくれるだろうか？",
  str_files_story_des_4705 = "ストーリー5",
  str_files_story_des_4801 = "巨像の責任者にとって、日常業務のほかに「情報収集」も任務の一つだ。今回はダイナに同行する機会をうまく利用するのがよさそうだ。",
  str_files_story_des_4803 = "やはりキャラバンの仕事はそんなに楽じゃないわね…ダイナと一緒にどれだけの距離を歩いたか知れないわ。情報収集なんてもってのほか。立っているのもままならないくらい体力消耗しちゃった…",
  str_files_story_des_4805 = "ストーリー5",
  str_files_story_des_4807 = "ストーリー7",
  str_files_story_des_4902 = "ストーリー2",
  str_files_story_des_4904 = "ストーリー4",
