  str_files_story_des_5203 = "ストーリー4",
  str_files_story_des_5205 = "ストーリー6",
  str_files_story_des_5301 = "苦情の手紙の中心地と言えば、ジョムは確かにそのうちの一人だ。ところかまわず商品並べるわ、やたらセールスを掛けまくるわ、本当に困ってしまう。今日はジョムに会いませんように…",
  str_files_story_des_5303 = "ジョムはなぜこんなにも「勤勉」に金儲けに励むのだろう？良くない嗜好があるわけでもなさそうだが、何か別に隠された事情があるのかもしれない。",
  str_files_story_des_5305 = "ストーリー5",
