  str_files_story_des_10101 = "【準備中】",
  str_files_story_des_10201 = "立て続けに起こる戦闘に誰もが休息をとれず、皆持ちこたえられなくなってきた。最大の敵は暗鬼ではなく、疲れなのかもしれない…",
  str_files_story_des_10202 = "エンジェルの要求をきっかけに巨像のもう一つの部屋の真の使い道を知ることができた。そしてエンジェルの別の一面を発見した…",
  str_files_story_des_10203 = "「可哀相な」ドーヴ、どうやらゆっくり休めないようだ。なにかいい方法を考えた方がよいだろうか？ドーヴはナマケモノではあるが、まったく仕事をしていないわけではない…あくまで彼女自身の言い分ではあるが。",
  str_files_story_des_10204 = "口の達者なゾーヤが相手では、要求をのむしかない。結果はゾーヤの満足いくものではなかったけど、目的は達することはできたようだ…",
  str_files_story_des_10301 = "シェルター28号にソラヴァンがいる間、カロンがシェルター28号と啓光連邦のことを説明してくれた。それはあなたがこの世界を知る助けになったはず。",
  str_files_story_des_10302 = "モンドルの1件の後、あなたはヒイロとソラヴァンの中をぶらぶらしていた。空の末裔への好奇心からか、ヒイロは普段なかなか口にしないことを久しぶりに口にした。",
  str_files_story_des_10303 = "時間が空くたびに、バイスは巨像の各種パラメーターを測っている。まさか巨像になにかおかしなことでもしようとしてるのだろうか？…",
  str_files_story_des_10304 = "カレンとバイスは白夜城で過ごした日々のことを語り合い、白夜城の統治秩序について「友好的」な討論を繰り広げた…",
  str_files_story_des_10305 = "ほんのわずかな期間離れていただけで、カナン城の日常業務は混乱に陥り、誰一人としてなすすべがない。それを知ったビビアンは事を解決するために駆け付け、こうしてあなたもビビアンの「恐ろしく」高い能力を目の当たりにすることになる…",
  str_files_story_des_10306 = "謎の人物が巨像の破損箇所を修理した。一体何が目的なのか？ただのゲームにすぎないのか？それとも啓光連邦の最新装備のテストなのか！？",
  str_files_story_des_10307 = "グリードで一度会っただけの謎の人物「ファウスト」が再び巨像に現れた。しかも、自分に関する「調査報告書」を持って…？",
  str_files_story_des_10308 = "天空ノ谷へと出発する前、バイスと一緒に入院中のビビアンの見舞いにいくことにした。しかし、その道中バイスの財布が突然なくなった…誰かに盗まれたのだろうか？",
  str_files_story_des_20100 = "【準備中】",
  str_files_story_des_20101 = "ガルーが突然、あなたに一緒に巨像の整備をしようと言ってきた。対決ゲームもしようと要求し、もしあなたが負けたら巨像にすこし「余計な」ことをさせてもらいたいという…",
  str_files_story_des_20200 = "ヒイロにカナン城の観光へ誘われた。彼女はあなたに1枚の奇妙な紙を渡し、啓光連邦の将軍と「紙」にまつわる話を語り始めた。",
  str_files_story_des_20201 = "ある時啓光の会議の後、バートンが突然訪ねてきて何やら状況を説明する。それもこれもあなたがほかの3名の将軍に「食べられて」しまうと、バートンが心配したかららしい。",
  str_files_story_des_20202 = "そもそも戦うことはバートンにとってどんな意義を持つのか尋ねるだけのはずが、無理やりチェスに付き合わされる羽目に。バートンの一方的な勝利宣言の後、バートンは「勝利」こそが戦う意義だと告げる。",
  str_files_story_des_20203 = "睡眠についての悩みを、キシローナはお得意の方法で解決してくれた。この長官の解決方法は少々荒っぽいが、シンプルかつ効果的で、一度ですべてを解決してしまう。",
  str_files_story_des_20204 = "自分の部屋に戻ると、謎のメモが残されていた。感知能力で調べてみると、どうやらヒイロ長官と関係があるようだ。そしてヒイロと対峙する中、真相がだんだんと明らかになっていく。",
  str_files_story_des_20205 = "巨像でラスは何かに悩んでいるようだ。あなたが近づいていくと、なんだかおかしな雰囲気になり、暗闇の中でひそかに「追いかけっこ」が繰り広げられる。",
  str_files_story_des_20300 = "幻と喜びに溺れたい？それとも真実の苦痛を堪能したい？「旧夢」は両手を広げて、真理結社の一角をのぞき見ている。",
  str_files_story_des_20301 = "「なにがなんでも明日がどうなるのか知りたい」と言うのなら、ビクトリアはもちろん、あなたの選択を尊重するだろう…",
  str_files_story_des_20302 = "ファウストのセティの世話をするのは実に一苦労だ。というのもセティの性格は猫のようだからだ。",
  str_files_story_des_20303 = "正真正銘のグルメ王は超ビッグサイズの肉であろうとツルや砂、泥であろうと何でも飲み込めるのだ。だがニンジンだけは…",
  str_files_story_des_20304 = "巨像の上に静かに佇むネイルスは、生気がなく、弱々しく見える。彼はとても落ち着いた目をしており、何事にも動じないかのようだ。しかし、それは見た目だけのことかもしれない…",
  str_files_story_des_20400 = "ナビゲーターはふと思い立ち、クラリンの料理の味を確かめにカフェに行くことにした。しかし途中で言いあいから取っ組み合いの大げんかになったリオナとヒドライに遭遇してしまう。2人の肉弾戦は巨像内では日常茶飯事のようだ。解決のため、ナビゲーターはクラリンに助けを求めた。",
  str_files_story_des_20401 = "夢の中で「おかしな声」を聞いたことで、あなたは睡眠不足になり、気持ちも緊張状態に。それを聞いたクラリンは助けになってくれると言って、自らの経験から状況を分析判断してくれた。その「おかしな声」の正体が出現するまで…",
  str_files_story_des_20402 = "ヒドライはあなたが現れたことをとても意外に思い、あなたが白夜城に行かなかったことを知るとクレーケンに対する態度がますます悪化した。ヒドライとクレーケンの関係はどうやらあまり良くないらしい。尋ねてみると、ヒドライは昔のあることを話しだした…",
  str_files_story_des_20403 = "「影狼」が夜中にこっそり部屋に入ってきたのに気づいたあなたは、ヒドライを訪ね、「影狼」をしっかり大人しくさせておくようお願いする。しかし相手はなんと「それはできない」と言ってきた？",
  str_files_story_des_20404 = "ジェーンは記録者として静かにすべてを見守ってきた。だが実は同時に周りの者も、冷淡さの下に隠れたジェーンの優しい心を見守り続けてきたのだ。",
  str_files_story_des_20405 = "リオナは普段、龍のサンストーンと片時も離れることがない。しかし最近サンストーンがリオナのそばにいない。また、サンストーンと一緒に姿を消したのは…",
  str_files_story_des_20500 = "「激闘応援」コンサート！ロック、激情、熱唱！現在オーディエンスを大募集中です！応募はジョムまでご連絡ください——",
  str_files_story_des_20501 = "身の程知らずのバーバラを完膚なきまでにぶちのめすには、パーフェクトでインパクトのある曲にしないといけない！！",
  str_files_story_des_20502 = "タイニーの最新発明品は「レジーナの極限デスメタアラーム」、「スーパーロケット調理器」それから「超クールなスポットライト」だ。",
  str_files_story_des_20503 = "スケジュールは満杯で、とてつもなく大きなストレスにオティは今にも押しつぶされそうだ。このままだとオティは…",
  str_files_story_des_20504 = "霞の光が透明な瓶の中できらめき、まるで小さな夢の世界かのように美しい。バーバラはこういう美しさが好きだ。きっと彼女も素晴らしいお返しをしてくれるだろう。",
  str_files_story_des_20506 = "「タダより高いものはない」。ジョムの不思議なビッグプレゼントのように、安くてお得に見えても、事前にしっかり値段が付けられているのだ。",
  str_files_story_des_20600 = "【準備中】",
  str_files_story_des_20601 = "かつて北境の王宮で独り暮らしていたルイスはある日各地を旅するノーアに出会った。これは彼女たちの出会いの物語。",
  str_files_story_des_20602 = "ルイスは不眠に悩むあなたに新しいおとぎ話を聞かせてくれた。さらに気を遣って手作りのプリンを持ってきてくれたけど、この甘い香りの漂うプリン、なにかおかしい気がする…",
  str_files_story_des_20603 = "ベツレヘムからルイスとノーアの勉強を見張るよう頼まれた。しかし、ふとしたきっかけで自分まで「巻き込まれる」とは、誰が想像しただろうか…",
  str_files_story_des_20604 = "最近張りつめている神経をやわらげるため、少し花を分けてもらえないかとナシリスに聞いた。すると、ナシリスは希望通り大量の花を用意してくれたが、数を少々誤解しているような…？",
  str_files_story_des_20605 = "光霊の能力に関するデータを分析したいと思い、「なんでも知っている」と言われるノーアに相談してみた。ノーアは自分の能力を使って「完璧」なデータを一式提供してくれたが、結果はあまり「完璧」でないようだ…",
  str_files_story_des_20606 = "掃除を手伝いに来ただけのノーアだったが、突然潔癖症の発作を起こし、小さな汚れ1つのために半日以上を費やして繰り返し同じ壁を拭いていた。あなたは自分がやった方がマシだと思った。",
  str_files_story_des_20607 = "オフィラは巨像内の他の人ともっと仲良くするために、「他人に自分の角を触られる」ことに対する抵抗感を克服しようと考えた。そのため、彼女はナビゲーターを練習相手に選んだのだった。",
  str_files_story_des_20700 = "【準備中】",
  str_files_story_des_20701 = "うわさの「閃光ピョンピョン」を探していると、喧嘩中のボンバーとラビに出くわした。2人はあなたを引き留め、奇妙なことに喧嘩の是非を判定しろと言う。そして間もなくあなたは知るのである。探していた「閃光ピョンピョン」とはまさに…",
  str_files_story_des_20702 = "マギーがあちこちを何か探し回っている。とても慌てている様子だが、恥ずかしがり屋のマギーはいろいろな所を探さないと失くした物は見つからないだろうと聞いて、なんと…？",
  str_files_story_des_20800 = "【準備中】",
  str_files_story_des_20801 = "エイミーは正式な法廷の騎士のように巨像の中を巡回し、皆の悩みを解決しようと頑張っているが、結果はあまりよくないようだ。そこで彼女はあなたを誘うことにした…",
  str_files_story_des_20802 = "巨像で何やら大事件が発生したようだ！白夜城の裁判長までもが自ら調査に乗り出した。一体何が起こったのだろう…",
  str_files_story_des_20803 = "ミジェンニがまた何かを裁定している。しかし今回の裁定価格は…あまりにも突飛すぎやしないだろうか？",
  str_files_story_des_20900 = "【準備中】",
  str_files_story_des_20901 = "ラファエルが巨像の秘密を発見した？しかも巨像の治療を試みる？ラファエルは以前、巨像に似た仲間を治したことがあるのだという…",
  str_files_story_des_20902 = "炎を操ることはできるが、ウリエルはしょっちゅう悲観的になる。あなたは彼女にぬくもりを与えることができるか？",
  str_files_story_des_20903 = "「ゆっくりは安定、安定こそがスピード」。ガブリエルの言葉にあなたは頭がこんがらがってしまう。しかし、時には休むことも確かに良いことだ。",
  str_files_story_des_20904 = "偶然がきっかけで、あなたが黎明変晶石をミカエルにプレゼントすると、少女の穏やかな心の水面にわずかな波紋が浮かんだようだ。",
  str_files_story_des_21000 = "巨像内で突然、奇妙な詩歌コンテストが始まった。審査員に選ばれたあなたは、誰の詩を気に入るだろう？",
  str_files_story_des_21001 = "キーティン聖歌隊の4人組に「一体誰が男の子で、誰が女の子なのか」と尋ねてみた。すると、彼らは彼らが用意したテストにパスしたら、正解を教えてくれると言う。",
  str_files_story_des_21002 = "キーティンはソルラドが休んでいる隙に花をソルラドの耳に挿した。ソルラドは怒って、あなたにこの件を処理するよう要求した。そしてあなたたちは力を合わせ、特別な「事件記録」を生み出すことになる…",
  str_files_story_des_21003 = "あなたはキーティン聖歌隊と自分から積極的にコミュニケーションをとり、彼らに「話し方を変えてほしい」と伝えた。努力の甲斐あって、子どもたちはあなたの気持ちを汲み取り、願い出を断った。",
  str_files_story_des_21004 = "深夜どこからともなく美しい旋律が聞こえてきた。だが、そこにはなぜか恨みがましい泣き声が混じり、サビに入ったところで突然止まってしまった。",
  str_files_story_des_21005 = "巨像の片隅に誰かが奇妙な「白い花」を「植えた」。調査すると、どうやらユーライアが植えたようだが、一体…なぜなのだろうか？",
  str_files_story_des_21100 = "イスタバンは3通の封筒を送ってきた。そしてその中の1通を持って、彼らと面会するようあなたに要求した。あなたは調べあげた全ての情報を記録した後、最終的な選択をする…",
  str_files_story_des_21101 = "クレーケンは回りくどい方法で、あなたを「預言ゲーム」に誘った。最後にようやくあなたは彼の本当の目的を知る…",
  str_files_story_des_21102 = "クレーケンはギフトの「チボリの冒険図」を受け取ると一緒にやろうとあなたを誘う。そしてついでに「彼と冒険図」についての奇妙な物語を語り始めた…",
  str_files_story_des_21104 = "この1杯の酒を飲んでみよう！うその味は甘く優しいのに、「忠心と誠実」の味はなぜこんなにも苦いのだろう。",
  str_files_story_des_21105 = "カフェが滅茶苦茶に荒らされ、棚に入っていた食べ物がすべて消えていた。そして、最初に現場に到着した人物であり、最も有力な容疑者となったのはメッセージを送ってきたセレウコスだった…",
  str_files_story_des_21106 = "パテとパシの二人とかくれんぼした時のことを思い返してみると、彼女たちの歌は本当に不気味で怪しげだった。しかし、あの歌を聞いてホッとすることになるとは…",
  str_files_story_des_21200 = "法廷？裁判？啓光連邦の支援本部内で犯罪？真相はいかに？",
  str_files_story_des_21201 = "ビビアンはいつも忙しい。巨像にいてもそれは変わらない。しかし、ねぎらいの飲み物を受け取ると、おかしな反応を見せた…",
  str_files_story_des_21202 = "あなたのねぎらいに感謝するため、ビビアンが「ビッグプレゼント」を用意してくれた。彼女の熱いもてなしに、あなたは耐えきることができるか？",
  str_files_story_des_21204 = "普段は「華麗な姿」のカロンが最近突然謎めいた様子に変わった。どうやら蛍灯に興味があるようだが、それは一体なぜだろう？",
  str_files_story_des_21205 = "たまたまバイスに出くわしたところ、今彼女は非常に難しい計画に携わっているという。あなたは手伝ってあげられるか？",
  str_files_story_des_21206 = "啓光連邦の監察長官から突然の依頼が！しかも依頼内容は代わりにギフトを届けることだという。本当にそれだけなのだろうか？",
  str_files_story_des_21207 = "フィリスにとってもユミにとっても、チーズは止めのツボ。チーズを見ると2人とも大騒ぎになる。一体チーズが彼女らに何をしたというのか？",
  str_files_story_des_21300 = "毎週、ソルラドは1時間ほど「消える」。一体何をしているのだろう？",
  str_files_story_des_21301 = "ナディーンが突然、あなたのためになにかしたいと言い出した。その努力と気遣いに感動していたあなただったが、ある日彼女が謝ってきた。ある出来事がすべての始まりだという…",
  str_files_story_des_21302 = "Ms.ブランの「ガイド」という身分に興味を持ったあなただったが、却ってMs.ブランのナビゲーターへの興味に火をつけてしまう。こうして奇妙な駆け引きが始まった。",
  str_files_story_des_21303 = "「蛍灯トモモ」を拾ってからというもの、カレンはあなたの育ての「母親」に随分と興味をもつようになった。そしてついに、あなたが感知した彼女の母親の記憶について、話し始めた…",
  str_files_story_des_21304 = "巨像の中をブラブラしながらソルラドの脇を通ると、なんと呼び止められた…",
  str_files_story_des_21400 = "「砂漠の果て」は一体どこにあるのだろう。そして決死隊は、どこへ向かうのだろう。",
  str_files_story_des_21401 = "伝説の「天災の悪魔」は悪の限りを尽くし、「天災の悪魔」が現れた所はまるで天災に見舞われたかのように壊滅状態になる。彼女には5億という高額懸賞金が掛けられている。",
  str_files_story_des_21402 = "心配で気が気でないカフカとぼうぜんとするナビゲーター。すべてはフランツの失踪が原因だ。この広い巨像の中で、「忠実な黒犬」は一体どこに行ったのだろうか？",
  str_files_story_des_21403 = "大きいってのはいいこと、高いってのは強いってこと、重いってのは力があるってこと。雪辱を果たすため、ソクは再びクマに挑戦状を叩きつけた…",
  str_files_story_des_21404 = "劣悪なニセモノの山を買わされたヘールは、ジョムを探し出して話をつけようとする。しかし、いつの間にかジョムに言いくるめられ、またも奇妙な新商品を買わされてしまう。今度ばかりはナビゲーターでも救いようがなかった…",
  str_files_story_des_21500 = "ミジャードは巨像内に「上級暗鬼」が侵入していることに気づき、ターゲットをカフェに閉じ込めた。あなた達はその暗鬼から重要な情報を聞き出すために「尋問のプロ」達を集めた。その結果、分かったことは…",
  str_files_story_des_21501 = "どちらが強いのかという問題に関して、ベニとクロは「友好」的な「尋問」を始めた。二人に詰問された末、あなたは自分の考えを口にした。コンビの意義はお互いの欠点を補うことに他ならない。わざわざ競う必要などないのだ。",
  str_files_story_des_21502 = "ミジャードへのクレームがますます増え、人を「不快」にさせる行動について彼女と話し合わくてはならなくなった。しかし、最終的には、あなたが皆の身代わりになってしまうことに…？",
  str_files_story_des_21503 = "エルシーの部屋からは、いつも謎の叫び声が聞こえてくる。真相を突き止めるため、勇気を振り絞って彼女に聞いてみた。すると、彼女はあなたを部屋に案内してくれることに…",
  str_files_story_des_21504 = "あなたがワタリに送ったプレゼントは、彼の医者だった時の記憶を呼び起こしたようだ。",
  str_files_story_des_21600 = "人の心の中の想いを読み取れる奇怪なカセット。テッサ、シャリー、アイリーナはこのカセットとどう向き合うのだろう？",
  str_files_story_des_21601 = "テッサはあなたがプレゼントした光力笛飴を受け取った。だが、それが暗い過去をよみがえらせてしまう…",
  str_files_story_des_21603 = "アイリーナは新しい服を買いたがっているが、様々な理由で実現できずにいる。この少女は想像以上に重い「呪い」を背負っていたのだ…",
  str_files_story_des_21604 = "何か話したいことがある様子のシャリーだったが、実は自分の祖父の「死の謎」を探るために苦労を重ねていた。果たして、白夜城の天使であるガブリエルがどう関係しているのだろうか…",
  str_files_story_des_21700 = "3つのお話を3人で。3つのお話を1人で。一体1なのか3なのか、それとも…？",
  str_files_story_des_21701 = "スカーレイが話してくれた奇妙な物語。だが、物語といい、それに対するスカーレイの態度といい、どこか意味深長なものに思える…",
  str_files_story_des_21702 = "バーバリーは自分の祖先と貴族精神にまつわる事を話してくれた。貴族としての精神には敬服したが、同時に若干の違和感を覚えた…",
  str_files_story_des_21703 = "コンスタンは北境で暗鬼狩りをしていた時のことを話してくれた。しかし、その狩りの話は聞けば聞くほど不思議に思えてきた…",
  str_files_story_des_21800 = "あなたは突然サメヤマからR・Wの祝典に招待され、おまけにドーンの世話を暗に頼まれた。そして、祝典会場に足を踏み入れて、ようやく気づく。この祝典、全ては自分たちを歓迎するために準備されたものだったのだ。",
  str_files_story_des_21801 = "イブは深夜に「火薬」や「硫黄」の類を探しているようだ。一体何をするつもりなのだろう…",
  str_files_story_des_21802 = "R・Wのボスであるサメヤマが急に、R・Wを一番よく表している物は何かと聞いてきた。話していくうちに、サメヤマはある人にプレゼントを用意したいらしいことが判明する…",
  str_files_story_des_21803 = "最近、ドーンは何か悩みを抱えているようだ。彼女の力になってあげよう…",
  str_files_story_des_21900 = "秘密の月の約定がいよいよやってきた。親愛なる「名無し」よ、おススメの1冊をたずさえ、月の下で共に本の世界を楽しもう。",
  str_files_story_des_21901 = "悪夢に苦しみ続けるベリエも、両手が本に触れている時だけはつかの間の安らぎを得られる…",
  str_files_story_des_21902 = "グラスの中から「麗人」が見つめている。永遠に会うことの叶わぬ彼女をあなたはただ見つめることしかできない。",
  str_files_story_des_21903 = "今晩8時30分、ラド・ヤーンホール。世界で最も謎に包まれ、美しく偉大な交響詩があなたを迎え入れる。",
  str_files_story_des_23001 = "喧嘩して戻ってきたばかりのダイナに偶然出くわした。怪我を心配したら、逆に喧嘩に関する専門知識を教えられた。しかしロビンがやってくると、ダイナは慌てだした。ダイナが怪我をした原因は、ロビンだったのだ…",
  str_files_story_des_23101 = "あなたは2ｍの距離を保ちながら、ロビンがダイナにピッタリのプレゼントを選ぶのを手伝う。しかしロビンのプレゼント選びのセンスはどうみても変わっていた…",
  str_files_story_des_23201 = "最近あなたはミヤのもう1つの人格である「バーバ・ヤーガ」にいじめられてばかりだ。そこでミヤに尋ねてみたところ、「バーバ・ヤーガ」があなたをいじめるのは、怒らしてはいけない――「あの人」を怒らせたからだとわかった。",
  str_files_story_des_23301 = "最近、クスッタはいつも朝早くに出かけて夜遅くに帰ってくる。心配になってクスッタに何かあったのか聞いてみた…するとクスッタはあなたを「彼女」の墓に連れて行った。",
  str_files_story_des_23401 = "タキは金色のサンドワームを探してほしいという奇妙な依頼を受けた。あなたとタキは一緒にサンドワームの故郷であるR・W砂漠に向かい、世界でただ一つの特別なサンドワームをみつけ出そうとした。しかし、非常に高価な黄金サンドワームが、ヘールによって金色のサンドワームプロテインにされてしまう！？",
  str_files_story_des_23501 = "たくさんの人に好かれてしまうと悩むフェラール。またいつもの心配性が始まった。さあ、一体どう慰めてあげよう？",
  str_files_story_des_23601 = "みんなスモーキーにいい印象をもっていないようだ。そこで始動したのが、スモーキーのイメージアップ計画だったのだが…",
  str_files_story_des_23701 = "病気ではない「病」を「患った」ナビゲーターに対し、グラムは薬とは言えないような「薬」を使って治療したが、案の定、効果は抜群だった。",
  str_files_story_des_23801 = "巨像の中に「巨像最強に挑戦」と書かれた謎の看板が現れた。一体どういうことなのだろうか…",
  str_files_story_des_23901 = "アルーラの大切なコレクションをうっかり割ってしまったが、彼女は意外な反応を見せた…",
  str_files_story_des_24001 = "巨像でパロマと一冊の本について語り合うことになった。パロマはどこか聞いたことのあるような、ないような物語を語り出す…",
  str_files_story_des_24101 = "ナルセールが巨像に植物の鉢植えをたくさん持ち込んだ。あなたはその中からサボテンを選び、寝室に置いて育て始めた。だが、数日後、奇妙なことが起こった…",
  str_files_story_des_24201 = "タタが突然、どんな女性が好きかと聞いて来た。一体急にどうしたのだろう…",
  str_files_story_des_24301 = "偶然ジェーンの書いた記録を見つけた。そこにはベセルの個人的な趣味について書かれていた。べセルは、この「証拠」を早急にも隠滅しようとするのだが…",
  str_files_story_des_24401 = "白火傭兵団の「交換市」に参加して以来…ルークのことがもっと分かった気がする。",
  str_files_story_des_24501 = "ピアタマンがいつもと打って変わって突然サングラスをかけ、助けを求めて来た…一体何が起こったのだろうか？",
  str_files_story_des_24601 = "光霊の間である秘密の画集が流行っているらしい。その画集にはあなたの作品が全て納められているという。画集の製作者は、どうやらあのスーツ姿の2人のようで…",
  str_files_story_des_24701 = "ジョムとヘイディに、何について話しているのか聞こうとしただけだったのだが、訳も分からず連れていかれた先で参加する羽目になったのは…「知恵比べ」？",
  str_files_story_des_24801 = "カーティは不測の事態のせいで、大量の仕事を抱えてしまった。手助けしてあげた方がいいだろうか？",
  str_files_story_des_24901 = "空腹を抱えたあなたの目の前にあるのは、ローラの焼いたハチミツケーキ。ローラが言うには、これを食べる前に必ずあることをしなければならないらしいのだが…",
  str_files_story_des_25001 = "巨像に驚くほど当たる読心術師がやって来たらしい。一体どうやって人の心を読むのだろう…",
  str_files_story_des_25101 = "シヴォーンは何か隠し事をしているようだ。尋ねてみよう。",
  str_files_story_des_25201 = "最近エリカは巨像で奇妙な声を聞くようになった。一体、何が起こっているのだろう…",
  str_files_story_des_25301 = "ルビーのリュックに、なぜこんなにたくさん他人の物が？ルビー自身にも訳が分からないようだ…",
  str_files_story_des_25401 = "ただならぬ様子のフロリナ。「大事な用事」とは…",
  str_files_story_des_25501 = "頼みたいことがあるから休憩室に来てほしい、とルージュに言われた。",
  str_files_story_des_25601 = "ある日のこと、神楽鈴の音が響いた。ゆったりとした足取りリンネが現れ、雲島の習慣を教えてくれた…",
  str_files_story_des_25701 = "カヤノは最近こそこそと行動が怪しい。何か悩みごとがあるようだ…",
  str_files_story_des_25801 = "アメモリが休憩室で特訓しているようだ。見に行ってみよう。",
  str_files_story_des_25901 = "ヨウが各地を渡り歩いて見聞きしたことを話してくれるらしい。",
  str_files_story_des_26001 = "モモとアンズから連絡があった。料理のことで話があるらしい。",
  str_files_story_des_26101 = "ハチとギンの紹介で、謎の生物が巨像へとやって来た…",
  str_files_story_des_26201 = "アズールからドライブに誘われた。車はパーティーが開かれている酒場の外に停められて…",
  str_files_story_des_26301 = "ロイが「新発明のテストの助手募集」の張り紙を出した。報酬はかなり出してくれるようだ。",
  str_files_story_des_26401 = "レノーアはぬいぐるみをつくろうと、あちこち材料を探し回っていた…",
  str_files_story_des_26501 = "ナビゲーターは巨像でギルスに会い、ギルスの創った「物語」の中に引き込まれてしまった。",
  str_files_story_des_26601 = "メイが端末で妙なメッセージを送ってきた。どうやら大事な話があるようだが…",
  str_files_story_des_26701 = "レインハトのそばで彼女の1日を垣間見るチャンス！？しかし、予定が想像と少し違っていて…",
  str_files_story_des_26801 = "新たな力を受け入れたバイスは、そのことが理由で今までの自分が消えてしまわないかと不安になっていた。彼女の悩みを解決するため、仲間たちとある「テスト」を思いつく…",
  str_files_story_des_26901 = "天空ノ谷で新しい力を手に入れたバートンは…少し様子がおかしい。これが錯覚であればいいのだが…",
  str_files_story_des_27001 = "ニナが手作りの「美食」を食べさせてくれるという。\nそれにまつわる物語も話してくれた…",
  str_files_story_des_27101 = "サナエが「メイド研修」の修了試験に参加することになった。\nしかし、その受験の条件は、何かがおかしい…",
  str_files_story_des_27201 = "カレンがある「密輸事件」で悩んでいたらしい。カレンの話を聞いてみよう。",
  str_files_story_des_27301 = "シエルの真剣な計画の数々…しかし、本音はどれもこれも、パワードスーツを装着して、あなたと一緒に海を見に行きたいだけだった。",
  str_files_story_des_27401 = "フィアがふくれっ面をしながら1人で廊下の真ん中に立っている。キャロもどこに行ったのか分からない…一体何があったのだろうか？",
  str_files_story_des_27501 = "メルト、サプリ、ファムの三姉妹が始めたインタビュー…ジェノはどう答えるのだろうか？",
  str_files_story_des_27601 = "船外公演のため、サーカス団のメンバーを載せてほしいとレインボーに頼まれた。しかし、いざ到着した先で、レインボーの気分が悪くなってしまう…",
  str_files_story_des_27701 = "ポルクスから影ノ街でのショッピングに誘われる。しかし彼女は、ある秘密の作戦を計画していた…",
  str_files_story_des_27801 = "キャスタからカジノへ行こうと誘われた。彼女が「幸運」に恵まれていると言われる理由が見られるだろうか？実に楽しみだ。",
  str_files_story_des_27901 = "あなたの願いに応え、イルンティが下級裁判官の仕事場を見学させてくれることになった。だが予想に反し、下級裁判官は居眠りの最中に、おかしな寝言を言っていた…",
  str_files_story_des_28001 = "ルーツをたどる旅は創作のインスピレーションを与えてくれると人は言う。リリカに付き添い、長年離れていた彼女の故郷へ帰ったのだが…",
  str_files_story_des_28101 = "ミノスからアンデルセン邸付近で行われる晩さん会に招待された。アンドーマ・アンデルセンが重要な発表をするらしい。",
  str_files_story_des_28201 = "義賊の精神とは何か、探求を続けているサディがタイミングよく手伝いを申し出てくれた。しかし、サディ自身の探求は決して順調ではないらしい。迷う彼女は、どう道を切り開くのだろう？",
  str_files_story_des_28301 = "アクセリアは「敗北」とはどのような感覚なのか知りたがっている。結局、彼女自身にとってとても新鮮な体験をすることができたのだろうか？非常に気になる。",
  str_files_story_des_28401 = "ベルタは白夜城の医学校を代表して、影ノ街で医学講演を行うことになった。しかし、彼女はどうも住民たちに歓迎されていないようだ。",
  str_files_story_des_28501 = "ゴルディは最近、珍しく不眠症になった。彼女を悩ませているものを知ったあなたは、一緒に問題を解決することにした。",
  str_files_story_des_28601 = "ヴィックに他の珍獣マスターから挑戦状が届いた！でも、どうやらまったく興味がない様子。本当に大丈夫なのだろうか…？",
  str_files_story_des_28701 = "ブランディに仕事を続けさせるため、あなたは彼女の密着取材に同意することに。けれど、記録をとるタイミングがちょっと微妙なようだ…",
  str_files_story_des_28801 = "シュウから双閣港の自宅に招かれたあなたは、張り切って出発の準備をすることにした…",
  str_files_story_des_28901 = "それぞれの思惑を胸に、双閣港の商業地域にやって来た\nあなたとユエ。そこで、とある「商人」に騙され…",
  str_files_story_des_29001 = "リンセイは突然降りかかった医療トラブルに怒り心頭だ。\nでも、そう簡単に諦める彼ではなく…",
  str_files_story_des_29101 = "バイスがR・Wに送った手紙の返事がないと小言を言っている。どうやら、イェリアに尋ねたほうがよさそうだ…",
  str_files_story_des_29201 = "いかにも重そうな郵便物の入った袋を持っているキア。あなたは自ら手伝いを申し出るのだが、そんなあなたを待っていたのは泣きわめく受取人だった…",
  str_files_story_des_29301 = "ティナが夢について語ろうとしている。でも単なる夢の話ではないようだ…",
  str_files_story_des_29401 = "ヒーローが女性を救うロマンチックなシーンに乙女心はトキメキます。ですが、その手のファンタジーはラインには無理です",
  str_files_story_des_29501 = "元囚人たちが主催するパーティーに参加したあなたとマシュー。空気を読まないマシューの言葉が皆を怒らせ、さらに檻に閉じ込められて…",
  str_files_story_des_29601 = "ハーティは偶然影ノ街でおかしな親子に出会う。女の子は言葉を話せなかったが、ハーティのことが気に入り、一方母親は娘をそのままハーティに預けてどこかへ行ってしまう…",
  str_files_story_des_29701 = "クリステンがある歌劇場のチケットをくれた。あなたは白夜城の歌劇場へと向かい、観劇することにしたのだが…",
  str_files_story_des_35001 = "インゲルに啓光の戦略準備室へ招待された。そこで何か新しいことを共有しようとしているようだ…",
  str_files_story_des_35002 = "アイアンソーン騎士団の物資が不足しているため、レオは部隊を率いて危険な暗面の奥深くまで探索に行かなければならなくなった。暗面に向かう途中、助けを求める避難民の集団に遭遇したレオは、ある選択をする…",
  str_files_story_des_35003 = "その日、アナトリアが会いに来て、休憩室に忘れてきた本を取ってきてほしいと頼まれた。",
  str_files_story_des_35004 = "ソルラドが遠くを見つめると、その意識は記憶の中のある場所へと向かい...",
  str_files_story_des_35005 = "人見知りでも、不器用でもいい。努力家で誠実なあなたを好きになる人が必ずいるから。",
  str_files_story_des_35006 = "「R・W砂漠に助けを求めている人あり」と占ったジャキーニ。だが占いには失敗するし、水晶玉も失くしてばかり。はたして任務を完了できるのか？",
  str_files_story_des_35007 = "旅は新しい体験をもたらすと同時に、見知らぬ人の姿に見慣れたものを見いだせるようになる",
  str_files_story_des_35008 = "蛍灯がMs.ブランの服を洗濯していたのだが、スカートについた痕がどうしても落ちない。いったい何の痕だろう？",
  str_files_story_des_35009 = "巨像のカフェで食事を楽しむセナと遭遇し、グルメや他の話題でちょっとした議論に…",
  str_files_story_des_35010 = "バップに「いいもの」をあげると訪れたデヌオ渓谷。はたして「いいもの」の正体は？",
  str_files_story_des_35011 = "いつでも笑顔を絶やさないローレライがここ数日ため息ばかりついている。何か悩みでもあるのだろうか？",
  str_files_story_des_35012 = "巨像の部屋で、昔どこかで見たことのある白い紙を見つけた――何かよくない記憶がすっと背筋を走ったかと思うと、紙を裏返す暇もなく、辺りを見回し、いつ目の前に現れてもおかしくない人影を探した。だが意外なことに、予想していた情景は現れなかった…",
  str_files_story_des_35013 = "あるさわやかな朝、ジョセリンから助けを求めるメッセージを受け取った。そこには「約束に出向く」ため、普段よりも早く一日の準備を終わらせなければいけないと書かれていた。ひとしきり忙しく駆け回った後、ジョセリンから一緒に約束の場所へ行こうと誘われた…",
  str_files_story_des_35014 = "知識欲あふれるアントニーは蛍灯を研究し、蛍灯に隠された秘密を解き明かそうとしている。",
  str_files_story_des_35015 = "ザーリャは最近バイスに精確な照準合わせを習っている。ザーリャの光力術を制御する力は上がったのだろうか？",
  str_files_story_des_35016 = "普通の光霊にはまだなじめていない33号だったが、新しい友人を作ろうと思っている。あなたの助けが必要だ。",
  str_files_story_des_35017 = "ファフニールが一日中ゲームをしているらしい。様子を見に行ってみよう。",
  str_files_story_des_35018 = "カンナが絵日記を見せてくれた。本当に気持ちのこもった絵日記だ！",
  str_files_story_des_35019 = "再びこの世界にやってきたトールがあなたのために特別な料理を作ってくれている。",
  str_files_story_des_35020 = "エルマが突然ソラヴァン内で働きたいという。いったいどういうことだろう？",
  str_files_story_des_35021 = "規則正しい健康的な生活は大事。夜更かしは禁物だ。",
  str_files_story_des_35022 = "レベッカは他人が自分の部屋に入るのを嫌がった。部屋の中にある秘密を知られたくないと思っているのは明らかだ…",
  str_files_story_des_35023 = "診療所の仕事に忙殺されるレベッカを見たイーサは、彼女がリラックスできるよい旅行先はないかあなたに尋ねようとした。でも、ただの姉にしては心配の度がやや過ぎるようだ…",
  str_files_story_des_35024 = "センキョクがお礼をしたいとナビゲーターを食事に誘った。ちょうど機巧術に興味をもっていたナビゲーターもたくさん話したいことがある。2人は意気投合して、食事をしながら、話に花を咲かせる。",
  str_files_story_des_35025 = "イスタバンが密かに通信を寄越した。どうやら身近な人には話せない事情があるようだ。",
  str_files_story_des_35026 = "バージルは影ノ街の骨董市場に行きたいようだ。ただ、一人で行く勇気がないようで……",
  str_files_story_des_35027 = "まさか、名高い浮遊商会の会長の手に不良債権があるなんて。",
  str_files_story_des_35028 = "時代を超越した発明を完成させるために、アルゴルはあなたを実験に誘おうとしています…",
  str_files_story_des_35029 = "シンゲイはアストラ大陸の新しいものを見てみたいと言い、あなたは彼女を影ノ街に連れて来た…",
  str_files_story_des_35030 = "ラショウはアストラで最初の妖怪退治の依頼を受けた。一体どんなもの遭遇するのだろうか…",
  str_files_story_des_35031 = "スノーシダーの森に危機が迫る中、ティアラはPlayerNameに助けを求め、二人は協力して罠を仕掛ける…",
  str_files_story_des_35032 = "レイチェルは最近ずっと食事の代わりに栄養剤を飲んでいる。それを知って、空の末裔は大いに驚く…",
  str_files_story_des_35033 = "ゼタは最近、何やらうずうずしているようだ。いったい何をたくらんでいるのやら。",
  str_files_story_des_30001 = "破産寸前の巨像を救うため、バイスは再び「一番の得意分野」――料理で活路を模索することに。一体どんな味の料理ができるのだろうか？",
  str_files_story_des_30002 = "彼女は二度と未知を恐れることなく、大海原の美しさと優しさを目の当たりにするだろう。あなたの手が彼女の手をしっかり握っていさえすれば。",
  str_files_story_des_30003 = "蜃気楼の幻の世界は複雑に絡み合う真の心そのもの。虚構の物語が彼の真実を映し出す。",
  str_files_story_des_30004 = "値段のついた商品をいくら買っても喜びや楽しみは得られない。しかし値段のつけられない贈り物は、ありとあらゆる悩みを消してくれる。",
  str_files_story_des_30005 = "風の音、鳥の声、そして波の音。あのホラ貝には海辺で過ごした夏の日のロマンチックな音が詰まっている。そしてあなたへの感謝の言葉も。",
  str_files_story_des_30006 = "バートンは啓光の海軍部隊を作るため、自ら遠征に出た…",
  str_files_story_des_30007 = "キシローナは毎年この時期になると、特別な服に着替え、誰も知らない場所へ行ってしばらく過ごしているようだ。しかし、今回はそれをうかがい知るチャンスがやってきたようだ…",
  str_files_story_des_30008 = "ヒイロが古い写真を見つめたまま物思いにふけっている。写真には彼女の昔の姿が記録されている。その思い出を記念にしてあげるにはどうすればいいのだろう？",
  str_files_story_des_30009 = "バイスがあなたの私物を見つけたようだ…それは遠い昔の思い出に関するものだ。線香花火に火をつけた彼女はいつもと何が違っているのだろう？",
  str_files_story_des_30010 = "影ノ街の大通りでジェーンと出会ったが、突然、近くにある孤児院から甲高い悲鳴が聞こえてきた…一体何があったのだろう？",
  str_files_story_des_30011 = "思わぬことがフィリスの怒りを買ってしまった！顔を見合わせるあなたとバイスをよそに、この事件の張本人は何事もなかったかのように、床に座って手を舐めながら、可愛い鳴き声を上げている。",
  str_files_story_des_30012 = "雨が降った後の空は、鳥が飛びたつのに向かない。それでも怪我をした小鳥は翼をはためかせる。この鳥が飛び立つ先は、テッサの心の行く先でもあるのかもしれない…",
  str_files_story_des_30013 = "ミジャードは仕事と研究にすべてを捧げている。そう、休みの時間でさえも…",
  str_files_story_des_30014 = "どこで手に入れたのか、セファーがビクトリアそっくりの衣装を着ている。彼女は一体何をしようとしているのだろう？",
  str_files_story_des_30015 = "突然カロンから劇の「招待状」を受け取った！なんとも言いがたい気持ちだが、それでも約束通り、会場へ赴くことに…",
  str_files_story_des_30016 = "別れの時が近づき、予報通りの雨がしとしとと降ってきた。来年の夏もまた、この情景をみられるのだろうか？",
  str_files_story_des_30017 = "アイリーナは不思議な魔法のドレスを手に入れた。「魔女」いわく、このドレスは深夜12時を過ぎると…？",
  str_files_story_des_30018 = "新年を迎えた日、おかしなプレゼントを受け取った。巨大な箱の中から、震動と奇妙なせき込みが聞こえる…",
  str_files_story_des_30019 = "鏡湖の湖畔で宴会をひとり抜け出したナシリスに出会った。ナシリスは湖面を見つめ、何か物思いにふけっているようだ。",
  str_files_story_des_30020 = "ビクトリアは不思議な鏡をもっている。この鏡が映し出すのは、あなた自身の姿ではない。",
  str_files_story_des_30021 = "ルイスとノーアはあなたを連れて、北境のある道の角で息をひそめている。目的は噂に聞く、休むことを知らない馬車を見るためなのだが…",
  str_files_story_des_30022 = "憂いも悩みも決して解消できないものではない。素敵なカフェと飲み物が3杯もあれば、時として簡単に解消できるのだ。",
  str_files_story_des_30023 = "新しい服に着替えたナディーンは、巨像で代わりを頼まれた用事も真剣にこなしている。ただ、彼女にはもう少し休んでもらいたいものだ…",
  str_files_story_des_30024 = "あなたは知識を身につけるため、お金を払って授業を受けることにした。驚いたことに、講師としてやって来たのはよく知っている人物――シャリーだった。",
  str_files_story_des_30025 = "ウリエルと夕陽の下で「文学交流」を行い…彼女に対する理解がさらに深まったようだ。",
  str_files_story_des_30026 = "照りつける日差しの中、自転車に乗ったマギーは大空へジャンプ！そして全力で何の罪もないキュリクに激突した…",
  str_files_story_des_30027 = "どこかから珍しい衣装を手に入れたというイブ。それを着てR・Wの人気者決定戦で皆を応援しようとしているようだが…",
  str_files_story_des_30028 = "カレンのこんな表情を見たのは初めてだ。驚き、不安、怒り。そして、どうすればいいかわからず、恥ずかしそうにまごついている。",
  str_files_story_des_30029 = "ラスに突然、江富の城の街歩きへと誘われた。これは…もしや、デート！？",
  str_files_story_des_30030 = "せっかくの休みだ。タタから、羽根つきで遊ぼうと誘われた。負けた人には罰ゲームがあるというのだが…",
  str_files_story_des_30031 = "桜の香りに心奪われない人などいるのだろうか？",
  str_files_story_des_30032 = "「赤浪サメ之助は妹、伊歩の平穏を願い、悪を成敗する旅に出た…」最近大人気だという東方の小説らしいが…？",
  str_files_story_des_30033 = "江富の城の駅で偶然イルンティに会ったが、思いがけず「取り調べ」をうけることに…",
  str_files_story_des_30034 = "チャンドラの心理カウンセリングは本当に不思議に満ちている。長いこと溜め込んでいた感情を解き放つと、一体どのような感覚なのだろうか？",
  str_files_story_des_30035 = "ベセルがイスタバンの服選び…どのような服を選んだのか、着ている姿を見るのがとても楽しみだ。",
  str_files_story_des_30036 = "クラリンがレースでバイトをすることに。しかし、彼女はどうしても最初の一歩を踏み出せずにいた…",
  str_files_story_des_30037 = "人形売りの少女が話してくれた、「審判の魔龍」の伝説…いや、この伝説の審判ってもしや…？",
  str_files_story_des_30038 = "猛暑、灼熱のカーブ、スリリングなレース。果たして、出場したタキの結果は…",
  str_files_story_des_30039 = "ラファエルの招待を受け、ある農園を訪れた。その農園のもてなしは「斬新」な工夫がされていた…",
  str_files_story_des_30040 = "彼女の胸がこれほど激しく高鳴ったことは今までなかった…",
  str_files_story_des_30041 = "ルイスに「おままごと」をしようと誘われた。それぞれどのような役を演じるのだろうか？",
  str_files_story_des_30042 = "アリスのケーキが誰かに食べられてしまったようだ。怒ったアリスは盗み食いの犯人に自ら裁きを下すことにした。",
  str_files_story_des_30043 = "フェラールはパンを作れる場所を探している…まさか転職するつもりなのだろうか？",
  str_files_story_des_30044 = "ヘールは「あるもの」を探すために新しい服を用意した。本人いわく、さらに素早く動ける服装らしい…",
  str_files_story_des_30045 = "リオナと一緒に海へ遊びに来たが…思いがけないことに、リオナが最も会いたくない「アイツ」に会ってしまった。",
  str_files_story_des_30046 = "スモーキーは怪盗となり、闇夜に紛れて計り知れない価値のある宝石を盗んでいった…しかし、盗まれたものは宝石だけではないようだ？",
  str_files_story_des_30047 = "ガルーが新しいゲームを開発した。クリアできないと溜まった巨像の修理代を返済することに…",
  str_files_story_des_30048 = "放たれたアマギリチョウの舞は、まるではかなく消える幻。しかし、ルークはその美しい光景を永遠に残す術を持っていた。",
  str_files_story_des_30049 = "水着に着替えたバーバリーが波とともに砂浜に現れた時、新たな伝説が生まれた…",
  str_files_story_des_30050 = "Ms.ブランへの恩を返そうと、彼女の臨時マネージャーをかって出た。しかし、この仕事は簡単ではなさそうだ。",
  str_files_story_des_30051 = "依頼を受けたあなたは、100箱もの酒をある場所に届けることになった。しかし、その依頼人はなんと…",
  str_files_story_des_30052 = "影ノ街で熱心に新聞のセールスをするウェンディに出会った。新たなキャリア開拓だろうか？",
  str_files_story_des_30053 = "スカーレイは「墓所」の守り手として、「墓所」に住まう死者の声にも耳を傾ける。",
  str_files_story_des_30054 = "ヘイディは要請を受け、カナン城で「1日護衛官」の職に就くことになった。しかし、業務開始直後から壁にぶちあたってしまう…",
  str_files_story_des_30055 = "伝説のチリソースを手に入れようと、レビィは影ノ街の監獄に潜入した。しかし、事態は彼女の予想とは違う方向へと発展し…",
  str_files_story_des_30056 = "ナビゲーターは謎の依頼を受けることになった。その依頼とは、ある有名な役者の取材だというのだが…",
  str_files_story_des_30057 = "黒バラ団の頭であるパロマがあなたを助手にしたいという。彼女の狙いは白夜城の貴族だ。しかし、それを追う裁判官の影が…",
  str_files_story_des_30058 = "ある休日、あなたはベツレヘムと共に本を読んでいた。偶然にも、チャーヤが何年も前に自身の想像を書き留めたノートを発見する…",
  str_files_story_des_30059 = "北境旅行に誘われたあなた。新年を迎える前の早朝、目を覚ますと氷の宮殿のほうからピアノの音が聞こえてきた。その音色を奏でていたのは、なんとノーヴィオで…",
  str_files_story_des_30060 = "カナン城で広がる「正義執行、a.k.a天罰代行」の伝説――たるんだ者のもとに、雷が落ちるとか…",
  str_files_story_des_30061 = "リリムたちは様々な性格をしているが、共通の「最高コマンド」を有している。その使命を果たすためならば、どんなことでもするつもりだ。",
  str_files_story_des_30062 = "常に研究熱心なシヴォーン。そんな彼女はガルーとのゲームを避けるため、コンサートのオーディションに参加することにした…",
  str_files_story_des_30063 = "1年に1度の冠月祭がやってきた。恋人たちの純粋な愛を守るため、一筋の電撃が街を突き抜ける…",
  str_files_story_des_30064 = "ピアタマンと白夜城の城門前で会う約束をしたあなたは、約束の場所へと向かう…",
  str_files_story_des_30065 = "クロエは貴族の結婚式に演奏者として招待された。しかし、彼女の作った楽曲が新婦に不安を与えてしまい…新婦が逃げ出すという大事件に発展！？",
  str_files_story_des_30066 = "影ノ街を歩いていたあなたは、突然、物陰から飛び出した見知らぬ大男に地下サロンに連れ込まれる。 そしてあなたはジェノと出会い…",
  str_files_story_des_30067 = "腕のいい狩人は変装を得意とする。警戒心を解いてこそ、獲物を追い詰めることができるのだ。",
  str_files_story_des_30068 = "影ノ街でフィア、ヴィック、シーラを見かけた。3人は何やら話している…",
  str_files_story_des_30069 = "街でダイナを見かけたあなたは声を掛けようとするが…",
  str_files_story_des_30070 = "ペギとクマがある依頼の手伝いをしてほしいと訪ねてきた。しかし、思いもよらぬことに簡単なお手伝いのはずが逃走劇を繰り広げることに…",
  str_files_story_des_30071 = "旅の途中、ある村を通りかかった。その村で補給物資を購入しようと思ったが、なんと村全体が牙を向けてきた。狂気に支配された住人たちに追われていた時、エルシーを見つけた…",
  str_files_story_des_30072 = "クスッタと一緒に影ノ街の連続殺人事件の調査を進めていた。恐ろしい犯人、ショックを受けた生存者を前に、クスッタが危機の中で輝かしい人間性を見せた…",
  str_files_story_des_30073 = "ガブリエルに影ノ街の孤児院への慰問を誘われ、2人で影ノ街にやって来ると…",
  str_files_story_des_30074 = "キーティンが偶然手に入れた黒魔法の禁書には最後のページに超恐ろしい魔法の精製方法が記載されていた。苦労の末に全ての材料を集め、精製を始めると…",
  str_files_story_des_30075 = "リアの勉強会を応援するため、ドレスアップしたシルヴァだが、それが思わぬ逆効果に…",
  str_files_story_des_30076 = "雲島では最近奇怪な事件が多発し、人々は恐怖におびえている。調査に乗り出したリンネは、黒猫による仕業だと気付く…",
  str_files_story_des_30077 = "トゲを持つイバラは邪悪な心を持つ人々によって神聖視され、祭壇に捧げられた。その後、下されたのは恩恵ではなく刑罰だった。",
  str_files_story_des_30078 = "異端調査団の極秘任務遂行のために航海に同行してほしいとフロリナから頼まれ…",
  str_files_story_des_30079 = "ビーチチェアに寝そべり、のんびりと潮風を感じる——ナルセールは忙しい仕事からようやく解放され、海辺の街で静かなひとときを満喫する。",
  str_files_story_des_30080 = "ミジェンニはサンドキャットを砂漠に送り返そうとするが、R・W砂漠に到着したとき、事態はそう簡単ではないことに気づく…",
  str_files_story_des_40101 = "あなたはカレンと共に多くの人で賑わう港町――双閣港へとやってきた。しかし、その旅の途中、招かれざる客に出会う…",
  str_files_story_des_40102 = "あなたはバイスに黙って双閣港に仕事をしにきた。だが、そこで見慣れた人物に出会う。",
  str_files_story_des_40103 = "オリエンタル調の服を着たパテとパシは、その服から思いがけない能力を手に入れて…",
  str_files_story_des_40104 = "イブとピクニックに行くと草原でたくさんのタンポポを見つけた。イブは少し考えた後に風にその願いをフーッと注ぎ込んだ。",
  str_files_story_des_40105 = "イルンティが今まで向き合えずにいた人物に会いに行くから、あなたに付き添ってほしいと言ってきた。裁判長をこれほど恐れさせる人物とはいったい誰だろう？",
  str_files_story_des_40107 = "小説出版の祝賀会の後、アイリーナはPlayerNameを浜辺の散歩に誘った。暖かな日差しの下、彼女はなにか話したいことがあるようで…",
  str_files_story_des_30081 = "ベツレヘム陛下が海辺で行われる交流関係樹立の記念式典に出席することになった。しかし2匹のドラゴンが現れ、大騒ぎになり…",
  str_files_story_des_30082 = "ヴィックと共に最も渇望するもの――金貨を探しに海に出た。この謎の海域で本当に見つけることはできるのだろうか？",
  str_files_story_des_30083 = "奇妙な鐘の音が4号博物館の中に響き渡る。夜の帳が下りたら、決してこの博物館に足を踏み入れてはいけない。さもなければ…",
  str_files_story_des_30084 = "1匹の特殊な暗鬼が北境近くに現れた。コンスタンはPlayerNameと共に見に行くことを決意する。",
  str_files_story_des_30085 = "ザーリャはかつての約束の場所――海辺へとやってきた。しかし、約束の相手が現れることはもうない…",
  str_files_story_des_30086 = "第5回ジュエリー大会に出場することになったニナ。優勝を手に入れるため、ニナは自ら宝石をまとい、カメラの前に立つ。しかし、撮れた写真にはどうしても納得がいかない。",
  str_files_story_des_30087 = "夢の話をしたところ、クラリンはPlayerNameに写真館へと連れていかれた。そこで、彼女夢の続きを見ることができるだろうか？",
  str_files_story_des_30088 = "カフカとPlayerNameは砂漠のレース場で一緒に体力増強の訓練に励むことになった。そこでカフカが紹介しようとした友人とは…",
  str_files_story_des_30089 = "不思議な手紙を受け取ったレビィ。そこには「弱い者を助けたい？だったら啓光研究室に来て」と書かれてあった。",
  str_files_story_des_30090 = "グラムはあなたを連れて厳しい道を進み、美しく静かな谷へとやってきた。まさか、ただ気分転換のためにここへ連れて来たのだろうか？",
  str_files_story_des_30091 = "シエルは独り倒壊した氷原の洞窟の中に閉じこめられてしまった。無事に危機を脱することはできるだろうか？",
  str_files_story_des_30092 = "タンドウと空の末裔は一緒に月を愛でながらおしゃべりを楽しんでいた。しかし話も盛り上がってきた頃、空の末裔はなんと居眠りをしてしまう。その夢に現れたのは、幼い頃のタンドウだった…",
  str_files_story_des_30093 = "ナディーンは双閣港で副業を見つけ、毎晩手に明かりを持ち海岸をパトロールしていた。そんなナディーンがある日、海へやってきた空の末裔に出くわす。",
  str_files_story_des_30094 = "釣り中の空の末裔を占いに従わせようと、なんと竜宮での経験まで持ち出してテンカンが説得を試み…",
  str_files_story_des_30095 = "シャリーがなんと非対称的なデザインの服を着た？それには実はやむを得ない事情が…",
  str_files_story_des_30096 = "公共イベントへの出演オファーを受けたリリカはサポートと励ましが欲しくて…",
  str_files_story_des_30097 = "ポルクスはある事情でしばらく離れることになった。その理由とは…",
  str_files_story_des_30098 = "ヒイロはお婆さんから手紙を受け取った。雲山の「封印」に最近妙な動きがあるらしく…",
  str_files_story_des_30099 = "家族団らんのとき、パソロは一人で窓辺に座り、紙を切り抜いて作った蝶々が彼女のそばに寄り添っていた…",
  str_files_story_des_30100 = "双閣港で偶然ファウストに会った。彼は古い書籍や古文書をたくさん買っていた。どうやら龍州の古い文化を研究しているようだ。",
  str_files_story_des_30101 = "センキョクが急に訪ねてきて、巨像を借りて遥か万里の星空を観測したいと言った。",
  str_files_story_des_30102 = "アドラスは素晴らしい未来を夢見ていたが、今ではすべて忘れてしまった。あなたが彼のために甲冑を作ったのをきっかけとして、彼は夢の断片を一時的に思い出した。",
  str_files_story_des_30103 = "戦闘で負傷したアクセリアは病床に横たわり、ベッドのそばにあるバラを見て悲観的になっていた。そのとき、PlayerNameが彼女にバラの意味を説明し始めた……",
  str_files_story_des_30104 = "閑散期のホテル「フルート・プラチナ」で、フェラールは支配人の招きに応じて設備のメンテナンスを行い、PlayerNameを「家族」として一緒に招待した…",
  str_files_story_des_30105 = "ウリエルは自分の陰鬱とした光霊人生を続けたくなくなり、禁書に記された魔法薬を飲んだ。そして、PlayerNameの前に現れたのは…",
  str_files_story_des_30106 = "依頼を受け、PlayerNameはロビンの住む所に本を届けに行った。そこで2人は怠惰な午後を過ごした…",
  str_files_story_des_30107 = "キシローナの依頼を受けて、PlayerNameは龍の像の残骸のある遺跡へとやってきた。そこで待っていたのは、礼服をまとったキシローナだった…",
  str_files_story_des_30108 = "いたずらをして面倒を引き起こしてしまったアンシアは罰として儀仗隊で訓練を受けることになってしまった。PlayerNameに手伝ってもらい、何とかごまかそうとするのだが…",
  str_files_story_des_30110 = "アイドルの仕事を終えた後、ゴルディと「1日プロデューサー」のPlayerNameは2人だけの時間を過ごす…",
