  str_files_story_des_30112 = "ティナは僕とボーンをピクニックに誘い、そのためにわざわざ新しい服まで仕立ててくれた。ところが、せっかくのお出かけは順調にはいかなかった……",
  str_files_story_des_30113 = "今日のR・Wはボンバーが厨房担当だ。料理のセンスにはいっさい恵まれていない彼女はなんと、PlayerNameを呼び、感知能力で食材との対話を試みようとする…",
  str_files_story_des_30114 = "狡猾な密猟者を捕まえるため、ヒドライは単身で乗り込む。ただあなたのことを信じて、援軍を待つ。",
  str_files_story_des_30115 = "最高のタニシ麺を作ろうと、ユエはまずタニシを捕まえるところから始めた…",
  str_files_story_des_30116 = "龍州の五色祭の季節がやってきた。「ぼんやりとした願い事を探すのじゃ」とシンゲイはあなたを連れて、にぎやかな街を巡り始めた…",
  str_files_story_des_30117 = "R・W砂漠での用事を済ませたPlayerNameは、砂漠で迷い、立ち往生しているインゲルに偶然出くわした。だがインゲルは決して道に迷ったのではないと言い張るのだった…",
  str_files_story_des_30118 = "セレブパーティに出席したあなたは、空の末裔に興味津々の人々に囲まれ、困ってしまう。そこに突如救世主のように現れたのは――",
  str_files_story_des_30119 = "まったく新しいステージでのコンサートに挑戦するバーバラだったが、R・Wのアイドルである彼女は壁にぶつかってしまう。PlayerNameは会場を満席にしてあげられるだろうか…",
  str_files_story_des_30120 = "看板店員となったラビから試食に誘われた。だが、多くの人においしい食べ物と笑顔を届ける前に、あなたを待っていたのは…",
  str_files_story_des_30121 = "波に打たれながら、イェリアの水着が見え隠れする。あなたはこの砂浜を守れるだろうか…",
  str_files_story_des_40001 = "タンドウは『大兆西域記』というタイトルの小説を読んでいる。とても不思議な内容の小説だが、タンドウは嫌いではないようだ。",
  str_files_story_des_40002 = "テンカンによると、ハッカチョウの「タゴ」がいなくなったらしい。彼が持ち歩いている『演天通神巻』で手がかりが見つかる…だろうか？",
  str_files_story_des_35034 = "ゲームではコウモリ亜人が悪役にされがちで、バティアはとても悲しんでいる。コウモリ超人がいてくれてよかった。",
  str_files_story_des_30122 = "長年昏睡していたバートンの上官パンゴが目覚めた。彼は急いであなたを呼び、上官と共に当時のことを振り返りはじめた……",
