  str_files_story_des_35036 = "ヴィルヘルムに宝探しへと連れて行かれ、100年前に埋められた古い物を掘り出した……",
  str_files_story_des_35037 = "ネイルスは昔の恩人を気にかけており、彼女が無事かどうかを確かめたがっている。",
  str_files_story_des_35038 = "ライザはあなたに最強の道具を調合しようと思ったのですが、ちょっとした問題が…",
